from dataclasses import dataclass
from datetime import datetime
from enum import StrEnum
from typing import Any


class RecipeDraftStatus(StrEnum):
    """Status of a recipe draft."""

    DRAFT = "draft"
    VALIDATED = "validated"
    REJECTED = "rejected"


@dataclass
class RecipeDraft:
    """Domain entity for recipe drafts generated by AI."""

    id: int | None = None
    user_prompt: str | None = None
    generated_content: dict[str, Any] | None = None  # Contains title, content, summary, etc.
    status: RecipeDraftStatus = RecipeDraftStatus.DRAFT
    created_at: datetime | None = None
    updated_at: datetime | None = None
    recipe_id: int | None = None  # Reference to the actual recipe if validated
